const i=JSON.parse('{"workId":"han-fei-zi","chapter":{"id":"han-fei-zi_ch-35","workId":"han-fei-zi","order":35,"title":"外儲說右下","difficulty":4,"estimatedMinutes":17,"passageIds":["han-fei-zi_ch-35_p-1","han-fei-zi_ch-35_p-2","han-fei-zi_ch-35_p-3","han-fei-zi_ch-35_p-4","han-fei-zi_ch-35_p-5","han-fei-zi_ch-35_p-6","han-fei-zi_ch-35_p-7","han-fei-zi_ch-35_p-8","han-fei-zi_ch-35_p-9","han-fei-zi_ch-35_p-10","han-fei-zi_ch-35_p-11","han-fei-zi_ch-35_p-12","han-fei-zi_ch-35_p-13","han-fei-zi_ch-35_p-14","han-fei-zi_ch-35_p-15","han-fei-zi_ch-35_p-16","han-fei-zi_ch-35_p-17","han-fei-zi_ch-35_p-18","han-fei-zi_ch-35_p-19","han-fei-zi_ch-35_p-20","han-fei-zi_ch-35_p-21","han-fei-zi_ch-35_p-22","han-fei-zi_ch-35_p-23","han-fei-zi_ch-35_p-24","han-fei-zi_ch-35_p-25","han-fei-zi_ch-35_p-26","han-fei-zi_ch-35_p-27","han-fei-zi_ch-35_p-28","han-fei-zi_ch-35_p-29","han-fei-zi_ch-35_p-30","han-fei-zi_ch-35_p-31","han-fei-zi_ch-35_p-32","han-fei-zi_ch-35_p-33","han-fei-zi_ch-35_p-34","han-fei-zi_ch-35_p-35","han-fei-zi_ch-35_p-36","han-fei-zi_ch-35_p-37","han-fei-zi_ch-35_p-38","han-fei-zi_ch-35_p-39","han-fei-zi_ch-35_p-40","han-fei-zi_ch-35_p-41","han-fei-zi_ch-35_p-42","han-fei-zi_ch-35_p-43","han-fei-zi_ch-35_p-44","han-fei-zi_ch-35_p-45","han-fei-zi_ch-35_p-46","han-fei-zi_ch-35_p-47","han-fei-zi_ch-35_p-48"],"tags":["法家","帝王術","法術勢"]},"passages":[{"id":"han-fei-zi_ch-35_p-1","chapterId":"han-fei-zi_ch-35","order":1,"canonicalText":"一、賞罰共則禁令不行，何以明之，明之以造父、於期。子罕為出彘，田恆為圃池，故宋君、簡公弒。患在王良、造父之共車，田連、成竅之共琴也。","sentenceIds":["han-fei-zi_ch-35_p-1_s-1","han-fei-zi_ch-35_p-1_s-2","han-fei-zi_ch-35_p-1_s-3"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"一、賞賜恩惠刑罰制裁共則禁令不行，何以明的，明的以造父、於期。子罕為出彘，田恆為圃池，所以宋君主統治者、簡公弒。患在王良、造父的共車，田連、成竅的共琴啊。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 1 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一、賞罰共則禁令不行，何以明之，明之以造父、於期」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一、賞罰共則禁令不行，何以明之，明之以造父、於期。子……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-2","chapterId":"han-fei-zi_ch-35","order":2,"canonicalText":"二、治強生於法，弱亂生於阿，君明於此，則正賞罰而非仁下也。爵祿生於功，誅罰生於罪，臣明於此，則盡死力而非忠君也。君通於不仁，臣通於不忠，則可以王矣。昭襄知主情，而不發五苑；田鮪知臣情，故教田章；而公儀辭魚。","sentenceIds":["han-fei-zi_ch-35_p-2_s-1","han-fei-zi_ch-35_p-2_s-2","han-fei-zi_ch-35_p-2_s-3","han-fei-zi_ch-35_p-2_s-4","han-fei-zi_ch-35_p-2_s-5","han-fei-zi_ch-35_p-2_s-6"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"二、治強生於國家法度法規，弱亂生於阿，君主統治者明於此，則正賞賜恩惠刑罰制裁而且絕不是仁下啊。爵祿生於功，誅刑罰制裁生於罪，臣下僚屬明於此，則盡死力而且絕不是忠君主統治者啊。君主統治者通於不仁，臣下僚屬通於不忠，則可以王矣。昭襄知主情，而且不發五苑；田鮪知臣下僚屬情，所以教田章；而且公儀辭魚。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 2 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「二、治強生於法，弱亂生於阿，君明於此，則正賞罰而非仁下也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「二、治強生於法，弱亂生於阿，君明於此，則正賞罰而非仁……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-3","chapterId":"han-fei-zi_ch-35","order":3,"canonicalText":"三、明主者、鑒於外也，而外事不得不成，故蘇代非齊王。人主鑒於士也，而居者不適不顯，故潘壽言禹情。人主無所覺悟，方吾知之，故恐同衣於族，而況借於權乎？吳章知之，故說以佯，而況借於誠乎？趙王惡虎目而壅；明主之道，如周行人之卻衛侯也。","sentenceIds":["han-fei-zi_ch-35_p-3_s-1","han-fei-zi_ch-35_p-3_s-2","han-fei-zi_ch-35_p-3_s-3","han-fei-zi_ch-35_p-3_s-4","han-fei-zi_ch-35_p-3_s-5","han-fei-zi_ch-35_p-3_s-6"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"三、明主的人或事物、鑒於外啊，而且外事不得不成，所以蘇代絕不是齊王。人主鑒於士啊，而且居的人或事物不適不顯，所以潘壽言禹情。人主無所覺悟，方吾知的，所以恐同衣於族，而且況借於權乎？吳章知的，所以說以佯，而且況借於誠乎？趙王惡虎目而且壅；明主的道，如周行人的卻衛侯啊。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 3 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「三、明主者、鑒於外也，而外事不得不成，故蘇代非齊王」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「三、明主者、鑒於外也，而外事不得不成，故蘇代非齊王。……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-4","chapterId":"han-fei-zi_ch-35","order":4,"canonicalText":"四、人主者，守法責成以立功者也。聞有吏雖亂而有獨善之民，不聞有亂民而有獨治之吏，故明主治吏不治民。說在搖木之本，與引網之綱。故失火之嗇夫，不可不論也。救火者，吏操壺走火、則一人之用也，操鞭使人、則役萬夫。故所遇術者，如造父之遇驚馬，牽馬推車則不能進，代御執轡持筴則馬鹹騖矣。是以說在椎鍛平夷，榜檠矯直。不然，敗在淖齒用齊戮閔王，李兌用趙餓主父也。","sentenceIds":["han-fei-zi_ch-35_p-4_s-1","han-fei-zi_ch-35_p-4_s-2","han-fei-zi_ch-35_p-4_s-3","han-fei-zi_ch-35_p-4_s-4","han-fei-zi_ch-35_p-4_s-5","han-fei-zi_ch-35_p-4_s-6","han-fei-zi_ch-35_p-4_s-7","han-fei-zi_ch-35_p-4_s-8"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"四、人主的人或事物，守國家法度法規責成以立功的人或事物啊。聞有吏雖亂而且有獨善的民，不聞有亂民而且有獨治的吏，所以明主治吏不治民。說在搖木的本，與引網的綱。所以失火的嗇夫，不可不論啊。救火的人或事物，吏操壺走火、則一人的用啊，操鞭使人、則役萬夫。所以所遇御臣心術權謀的人或事物，如造父的遇驚馬，牽馬推車則不能進，代御執轡持筴則馬鹹騖矣。是以說在椎鍛平夷，榜檠矯直。不然，敗在淖齒用齊戮閔王，李兌用趙餓主父啊。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 4 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「四、人主者，守法責成以立功者也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「四、人主者，守法責成以立功者也。聞有吏雖亂而有獨善之……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-5","chapterId":"han-fei-zi_ch-35","order":5,"canonicalText":"五、因事之理則不勞而成，故茲鄭之踞轅而歌以上高梁也。其患在趙簡主稅吏請輕重，薄疑之言國中飽；簡主喜而府庫虛，百姓餓而姦吏富也。故桓公巡民而管仲省腐財怨女。不然，則在延陵乘馬不得進，造父過之而為之泣也。","sentenceIds":["han-fei-zi_ch-35_p-5_s-1","han-fei-zi_ch-35_p-5_s-2","han-fei-zi_ch-35_p-5_s-3","han-fei-zi_ch-35_p-5_s-4","han-fei-zi_ch-35_p-5_s-5"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"五、因事的理則不勞而且成，所以茲鄭的踞轅而且歌以上高梁啊。他的患在趙簡主稅吏請輕重，薄疑的言國中飽；簡主喜而且府庫虛，百姓餓而且姦吏富啊。所以桓公巡民而且管仲省腐財怨女。不然，則在延陵乘馬不得進，造父過的而且為的泣啊。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 5 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「五、因事之理則不勞而成，故茲鄭之踞轅而歌以上高梁也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「五、因事之理則不勞而成，故茲鄭之踞轅而歌以上高梁也。……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-6","chapterId":"han-fei-zi_ch-35","order":6,"canonicalText":"右經","sentenceIds":["han-fei-zi_ch-35_p-6_s-1"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"右經。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 6 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「右經」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「右經」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-7","chapterId":"han-fei-zi_ch-35","order":7,"canonicalText":"說一","sentenceIds":["han-fei-zi_ch-35_p-7_s-1"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"說一。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 7 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「說一」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「說一」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-8","chapterId":"han-fei-zi_ch-35","order":8,"canonicalText":"造父御四馬，馳驟周旋而恣欲於馬。恣欲於馬者，擅轡筴之制也。然馬驚於出彘，而造父不能禁制者，非轡筴之嚴不足也，威分於出彘也。王子於期為駙駕，轡筴不用而擇欲於馬，擅芻水之利也。然馬過於圃池而駙馬敗者，非芻水之利不足也，德分於圃池也。故王良、造父，天下之善御者也，然而使王良操左革而叱吒之，使造父操右革而鞭笞之，馬不能行十里，共故也。田連、成竅，天下善鼓琴者也，然而田連鼓上，成竅擫下，而不能成曲，亦共故也。夫以王良、造父之巧，共轡而御不能使馬，人主安能與其臣共權以為治？以田連、成竅之巧，共琴而不能成曲，人主又安能與其臣共勢以成功乎？","sentenceIds":["han-fei-zi_ch-35_p-8_s-1","han-fei-zi_ch-35_p-8_s-2","han-fei-zi_ch-35_p-8_s-3","han-fei-zi_ch-35_p-8_s-4","han-fei-zi_ch-35_p-8_s-5","han-fei-zi_ch-35_p-8_s-6","han-fei-zi_ch-35_p-8_s-7","han-fei-zi_ch-35_p-8_s-8","han-fei-zi_ch-35_p-8_s-9"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"造父御四馬，馳驟周旋而且恣欲於馬。恣欲於馬的人或事物，擅轡筴的制啊。然馬驚於出彘，而且造父不能禁制的人或事物，絕不是轡筴的嚴不足啊，威分於出彘啊。王子於期為駙駕，轡筴不用而且擇欲於馬，擅芻水的利啊。然馬過於圃池而且駙馬敗的人或事物，絕不是芻水的利不足啊，德分於圃池啊。所以王良、造父，天下的善御的人或事物啊，然而且使王良操左革而且叱吒的，使造父操右革而且鞭笞的，馬不能行十里，共所以啊。田連、成竅，天下善鼓琴的人或事物啊，然而且田連鼓上，成竅擫下，而且不能成曲，亦共所以啊。夫以王良、造父的巧，共轡而且御不能使馬，人主安能與他的臣下僚屬共權以為治？以田連、成竅的巧，共琴而且不能成曲，人主又安能與他的臣下僚屬共至高權力威勢以成功乎？","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 8 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「造父御四馬，馳驟周旋而恣欲於馬」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「造父御四馬，馳驟周旋而恣欲於馬。恣欲於馬者，擅轡筴之……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-9","chapterId":"han-fei-zi_ch-35","order":9,"canonicalText":"一曰。造父為齊王駙駕，渴馬服成，效駕圃中，渴馬見圃池，去車走池，駕敗。王子於期為趙簡主取道爭千里之表，其始發也，彘伏溝中，王子於期齊轡筴而進之，彘突出於溝中，馬驚駕敗。","sentenceIds":["han-fei-zi_ch-35_p-9_s-1","han-fei-zi_ch-35_p-9_s-2","han-fei-zi_ch-35_p-9_s-3"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"一說道：。造父為齊王駙駕，渴馬服成，效駕圃中，渴馬見圃池，去車走池，駕敗。王子於期為趙簡主取道爭千里的表，他的始發啊，彘伏溝中，王子於期齊轡筴而且進的，彘突出於溝中，馬驚駕敗。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 9 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。造父為齊王駙駕，渴馬服成，效駕圃中，渴馬見圃池……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-10","chapterId":"han-fei-zi_ch-35","order":10,"canonicalText":"司城子罕謂宋君曰：「慶賞賜與，民之所喜也，君自行之。殺戮誅罰，民之所惡也，臣請當之。」宋君曰：「諾。」於是出威令，誅大臣，君曰「問子罕」也。於是大臣畏之，細民歸之。處期年，子罕殺宋君而奪政。故子罕為出彘以奪其君國。","sentenceIds":["han-fei-zi_ch-35_p-10_s-1","han-fei-zi_ch-35_p-10_s-2","han-fei-zi_ch-35_p-10_s-3","han-fei-zi_ch-35_p-10_s-4","han-fei-zi_ch-35_p-10_s-5","han-fei-zi_ch-35_p-10_s-6","han-fei-zi_ch-35_p-10_s-7"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"司城子罕謂宋君主統治者說道：慶賞賜恩惠賜與，民的所喜啊，君主統治者自行的。殺戮誅刑罰制裁，民的所惡啊，臣下僚屬請當的。宋君主統治者說道：諾。於是出威令，誅大臣下僚屬，君主統治者說道：問子罕啊。於是大臣下僚屬畏的，細民歸的。處期年，子罕殺宋君主統治者而且奪政。所以子罕為出彘以奪他的君主統治者國。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 10 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「司城子罕謂宋君曰：「慶賞賜與，民之所喜也，君自行之」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「司城子罕謂宋君曰：「慶賞賜與，民之所喜也，君自行之。……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-11","chapterId":"han-fei-zi_ch-35","order":11,"canonicalText":"簡公在上位，罰重而誅嚴，厚賦斂而殺戮民。田成恆設慈愛，明寬厚。簡公以齊民為渴馬，不以恩加民，而田成恆以仁厚為圃池也。","sentenceIds":["han-fei-zi_ch-35_p-11_s-1","han-fei-zi_ch-35_p-11_s-2","han-fei-zi_ch-35_p-11_s-3"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"簡公在上位，刑罰制裁重而且誅嚴，厚賦斂而且殺戮民。田成恆設慈愛，明寬厚。簡公以齊民為渴馬，不以恩加民，而且田成恆以仁厚為圃池啊。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 11 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「簡公在上位，罰重而誅嚴，厚賦斂而殺戮民」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「簡公在上位，罰重而誅嚴，厚賦斂而殺戮民。田成恆設慈愛……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-12","chapterId":"han-fei-zi_ch-35","order":12,"canonicalText":"一曰。造父為齊王駙駕，以渴服馬，百日而服成，服成請效駕，齊王王曰：「效駕於圃中。」造父驅車入圃，馬見圃池而走，造父不能禁。造父以渴服馬久矣，今馬見池，駻而走，雖造父不能治。今簡公之以法禁其眾久矣，而田成恆利之，是田成恆傾圃池而示渴民也。","sentenceIds":["han-fei-zi_ch-35_p-12_s-1","han-fei-zi_ch-35_p-12_s-2","han-fei-zi_ch-35_p-12_s-3","han-fei-zi_ch-35_p-12_s-4","han-fei-zi_ch-35_p-12_s-5"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"一說道：。造父為齊王駙駕，以渴服馬，百日而且服成，服成請效駕，齊王王說道：效駕於圃中。造父驅車入圃，馬見圃池而且走，造父不能禁。造父以渴服馬久矣，今馬見池，駻而且走，雖造父不能治。今簡公的以國家法度法規禁他的眾久矣，而且田成恆利的，是田成恆傾圃池而且示渴民啊。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 12 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。造父為齊王駙駕，以渴服馬，百日而服成，服成請效……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-13","chapterId":"han-fei-zi_ch-35","order":13,"canonicalText":"一曰。王子於期為宋君為千里之逐。已駕，察手吻文。且發矣，驅而前之，輪中繩引而卻之，馬掩跡。拊而發之，彘逸出於竇中，馬退而卻，筴不能進前也，馬駻而走，轡不能正也。","sentenceIds":["han-fei-zi_ch-35_p-13_s-1","han-fei-zi_ch-35_p-13_s-2","han-fei-zi_ch-35_p-13_s-3","han-fei-zi_ch-35_p-13_s-4","han-fei-zi_ch-35_p-13_s-5"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"一說道：。王子於期為宋君主統治者為千里的逐。已駕，察手吻文。且發矣，驅而且前的，輪中繩引而且卻的，馬掩跡。拊而且發的，彘逸出於竇中，馬退而且卻，筴不能進前啊，馬駻而且走，轡不能正啊。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 13 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。王子於期為宋君為千里之逐。已駕，察手吻文。且發……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-14","chapterId":"han-fei-zi_ch-35","order":14,"canonicalText":"一曰。司城子罕謂宋君曰：「慶賞賜予者，民之所好也，君自行之。誅罰殺戮者，民之所惡也，臣請當之。」於是戮細民而誅大臣，君曰「與子罕議之」。居期年，民知殺生之命制於子罕也，故一國歸焉。故子罕劫宋君而奪其政，法不能禁也。故曰子罕為出彘，而田成常為圃池也。令王良、造父共車，人操一邊轡而入門閭，駕必敗而道不至也。令田連、成竅共琴，人撫一絃而揮，則音必敗曲不遂矣。","sentenceIds":["han-fei-zi_ch-35_p-14_s-1","han-fei-zi_ch-35_p-14_s-2","han-fei-zi_ch-35_p-14_s-3","han-fei-zi_ch-35_p-14_s-4","han-fei-zi_ch-35_p-14_s-5","han-fei-zi_ch-35_p-14_s-6","han-fei-zi_ch-35_p-14_s-7","han-fei-zi_ch-35_p-14_s-8","han-fei-zi_ch-35_p-14_s-9"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"一說道：。司城子罕謂宋君主統治者說道：慶賞賜恩惠賜予的人或事物，民的所好啊，君主統治者自行的。誅刑罰制裁殺戮的人或事物，民的所惡啊，臣下僚屬請當的。於是戮細民而且誅大臣下僚屬，君主統治者說道：與子罕議的。居期年，民知殺生的命制於子罕啊，所以一國歸焉。所以子罕劫宋君主統治者而且奪他的政，國家法度法規不能禁啊。因此韓絕不是子評論說道：子罕為出彘，而且田成常為圃池啊。令王良、造父共車，人操一邊轡而且入門閭，駕必敗而且道不至啊。令田連、成竅共琴，人撫一絃而且揮，則音必敗曲不遂矣。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 14 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。司城子罕謂宋君曰：「慶賞賜予者，民之所好也，君……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-15","chapterId":"han-fei-zi_ch-35","order":15,"canonicalText":"說二","sentenceIds":["han-fei-zi_ch-35_p-15_s-1"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"說二。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 15 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「說二」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「說二」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-16","chapterId":"han-fei-zi_ch-35","order":16,"canonicalText":"秦昭王有病，百姓裏買牛而家為王禱。公孫述出見之，入賀王曰：「百姓乃皆裏買牛為王禱。」王使人問之，果有之。王曰：「訾之人二甲。夫非令而擅禱，是愛寡人也。夫愛寡人，寡人亦且改法而心與之相循者，是法不立，法不立，亂亡之道也。不如人罰二甲而復與為治。」","sentenceIds":["han-fei-zi_ch-35_p-16_s-1","han-fei-zi_ch-35_p-16_s-2","han-fei-zi_ch-35_p-16_s-3","han-fei-zi_ch-35_p-16_s-4","han-fei-zi_ch-35_p-16_s-5","han-fei-zi_ch-35_p-16_s-6","han-fei-zi_ch-35_p-16_s-7","han-fei-zi_ch-35_p-16_s-8"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"秦昭王有病，百姓裏買牛而且家為王禱。公孫述出見的，入賀王說道：百姓乃皆裏買牛為王禱。王使人問的，果有的。王說道：訾的人二甲。夫絕不是令而且擅禱，是愛寡人啊。夫愛寡人，寡人亦且改國家法度法規而且心與的相循的人或事物，是國家法度法規不立，國家法度法規不立，亂亡的道啊。不如人刑罰制裁二甲而且復與為治。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 16 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「秦昭王有病，百姓裏買牛而家為王禱」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「秦昭王有病，百姓裏買牛而家為王禱。公孫述出見之，入賀……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-17","chapterId":"han-fei-zi_ch-35","order":17,"canonicalText":"一曰。秦襄王病，百姓為之禱，病癒，殺牛塞禱。郎中閻遏、公孫衍出見之曰：「非社臘之時也，奚自殺牛而祠社？」怪而問之。百姓曰：「人主病，為之禱，今病癒，殺牛塞禱。」閻遏、公孫衍說，見王，拜賀曰：「過堯、舜矣。」王驚曰：「何謂也？」對曰：「堯、舜，其民未至為之禱也，今王病，而民以牛禱，病癒，殺牛塞禱，故臣竊以王為過堯、舜也。」王因使人問之何裏為之，訾其里正與伍老屯二甲。閻遏、公孫衍媿不敢言。居數月，王飲酒酣樂，閻遏、公孫衍謂王曰：「前時臣竊以王為過堯、舜，非直敢諛也。堯、舜病，且其民未至為之禱也。今王病而民以牛禱，病癒，殺牛塞禱。今乃訾其里正與伍老屯二甲，臣竊怪之。」王曰：「子何故不知於此。彼民之所以為我用者，非以吾愛之為我用者也，以吾勢之為我用者也。吾釋勢與民相收，若是，吾適不愛，而民因不為我用也，故遂絕愛道也。」","sentenceIds":["han-fei-zi_ch-35_p-17_s-1","han-fei-zi_ch-35_p-17_s-2","han-fei-zi_ch-35_p-17_s-3","han-fei-zi_ch-35_p-17_s-4","han-fei-zi_ch-35_p-17_s-5","han-fei-zi_ch-35_p-17_s-6","han-fei-zi_ch-35_p-17_s-7","han-fei-zi_ch-35_p-17_s-8","han-fei-zi_ch-35_p-17_s-9","han-fei-zi_ch-35_p-17_s-10","han-fei-zi_ch-35_p-17_s-11","han-fei-zi_ch-35_p-17_s-12","han-fei-zi_ch-35_p-17_s-13","han-fei-zi_ch-35_p-17_s-14","han-fei-zi_ch-35_p-17_s-15","han-fei-zi_ch-35_p-17_s-16","han-fei-zi_ch-35_p-17_s-17","han-fei-zi_ch-35_p-17_s-18"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"一說道：。秦襄王病，百姓為的禱，病癒，殺牛塞禱。郎中閻遏、公孫衍出見的說道：絕不是社臘的時啊，奚自殺牛而且祠社？怪而且問的。百姓說道：人主病，為的禱，今病癒，殺牛塞禱。閻遏、公孫衍說，見王，拜賀說道：過堯、舜矣。王驚說道：何謂啊？對說道：堯、舜，他的民未至為的禱啊，今王病，而且民以牛禱，病癒，殺牛塞禱，所以臣下僚屬竊以王為過堯、舜啊。王因使人問的何裏為的，訾他的里正與伍老屯二甲。閻遏、公孫衍媿不敢言。居數月，王飲酒酣樂，閻遏、公孫衍謂王說道：前時臣下僚屬竊以王為過堯、舜，絕不是直敢諛啊。堯、舜病，且他的民未至為的禱啊。今王病而且民以牛禱，病癒，殺牛塞禱。今乃訾他的里正與伍老屯二甲，臣下僚屬竊怪的。王說道：子何所以不知於此。彼民的所以為我用的人或事物，絕不是以吾愛的為我用的人或事物啊，以吾至高權力威勢的為我用的人或事物啊。吾釋至高權力威勢與民相收，若是，吾適不愛，而且民因不為我用啊，所以遂絕愛道啊。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 17 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。秦襄王病，百姓為之禱，病癒，殺牛塞禱。郎中閻遏……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-18","chapterId":"han-fei-zi_ch-35","order":18,"canonicalText":"秦大饑，應侯請曰：「五苑之草著、蔬菜、橡果、棗栗，足以活民，請發之。」昭襄王曰：「吾秦法，使民有功而受賞，有罪而受誅。今發五苑之蔬草者，使民有功與無功俱賞也。夫使民有功與無功俱賞者，此亂之道也。夫發五苑而亂，不如棄棗蔬而治。」一曰。「今發五苑之蓏蔬棗栗足以活民，是用民有功與無功爭取也。夫生而亂，不如死而治，大夫其釋之。」","sentenceIds":["han-fei-zi_ch-35_p-18_s-1","han-fei-zi_ch-35_p-18_s-2","han-fei-zi_ch-35_p-18_s-3","han-fei-zi_ch-35_p-18_s-4","han-fei-zi_ch-35_p-18_s-5","han-fei-zi_ch-35_p-18_s-6","han-fei-zi_ch-35_p-18_s-7","han-fei-zi_ch-35_p-18_s-8","han-fei-zi_ch-35_p-18_s-9"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"秦大饑，應侯請說道：五苑的草著、蔬菜、橡果、棗栗，足以活民，請發的。昭襄王說道：吾秦國家法度法規，使民有功而且受賞賜恩惠，有罪而且受誅。今發五苑的蔬草的人或事物，使民有功與無功俱賞賜恩惠啊。夫使民有功與無功俱賞賜恩惠的人或事物，此亂的道啊。夫發五苑而且亂，不如棄棗蔬而且治。一說道：。今發五苑的蓏蔬棗栗足以活民，是用民有功與無功爭取啊。夫生而且亂，不如死而且治，大夫他的釋的。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 18 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「秦大饑，應侯請曰：「五苑之草著、蔬菜、橡果、棗栗，足以活民，請發之」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「秦大饑，應侯請曰：「五苑之草著、蔬菜、橡果、棗栗，足……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-19","chapterId":"han-fei-zi_ch-35","order":19,"canonicalText":"田鮪教其子田章曰：「欲利而身，先利而君；欲富而家，先富而國。」","sentenceIds":["han-fei-zi_ch-35_p-19_s-1","han-fei-zi_ch-35_p-19_s-2","han-fei-zi_ch-35_p-19_s-3"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"田鮪教他的子田章說道：欲利而且身，先利而且君主統治者；欲富而且家，先富而且國。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 19 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「田鮪教其子田章曰：「欲利而身，先利而君」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「田鮪教其子田章曰：「欲利而身，先利而君；欲富而家，先……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-20","chapterId":"han-fei-zi_ch-35","order":20,"canonicalText":"一曰。田鮪教其子田章曰：「主賣官爵，臣賣智力，故自恃無恃人。」","sentenceIds":["han-fei-zi_ch-35_p-20_s-1","han-fei-zi_ch-35_p-20_s-2","han-fei-zi_ch-35_p-20_s-3"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"一說道：。田鮪教他的子田章說道：主賣官爵，臣下僚屬賣智力，所以自恃無恃人。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 20 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。田鮪教其子田章曰：「主賣官爵，臣賣智力，故自恃……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-21","chapterId":"han-fei-zi_ch-35","order":21,"canonicalText":"公儀休相魯而嗜魚，一國盡爭買魚而獻之，公儀子不受，其弟諫曰：「夫子嗜魚而不受者何也？」對曰：「夫唯嗜魚，故不受也。夫即受魚，必有下人之色，有下人之色，將枉於法，枉於法則免於相，雖嗜魚，此不必能自給致我魚，我又不能自給魚。即無受魚而不免於相，雖嗜魚，我能長自給魚。」此明夫恃人不如自恃也，明於人之為己者不如己之自為也。","sentenceIds":["han-fei-zi_ch-35_p-21_s-1","han-fei-zi_ch-35_p-21_s-2","han-fei-zi_ch-35_p-21_s-3","han-fei-zi_ch-35_p-21_s-4","han-fei-zi_ch-35_p-21_s-5"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"公儀休相魯而且嗜魚，一國盡爭買魚而且獻的，公儀子不受，他的弟諫說道：夫子嗜魚而且不受的人或事物何啊？對說道：夫唯嗜魚，所以不受啊。夫即受魚，必有下人的色，有下人的色，將枉於國家法度法規，枉於國家法度法規則免於相，雖嗜魚，此不必能自給致我魚，我又不能自給魚。即無受魚而且不免於相，雖嗜魚，我能長自給魚。此明夫恃人不如自恃啊，明於人的為己的人或事物不如己的自為啊。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 21 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「公儀休相魯而嗜魚，一國盡爭買魚而獻之，公儀子不受，其弟諫曰：「夫子嗜魚而不受者何也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「公儀休相魯而嗜魚，一國盡爭買魚而獻之，公儀子不受，其……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-22","chapterId":"han-fei-zi_ch-35","order":22,"canonicalText":"說三","sentenceIds":["han-fei-zi_ch-35_p-22_s-1"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"說三。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 22 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「說三」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「說三」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-23","chapterId":"han-fei-zi_ch-35","order":23,"canonicalText":"子之相燕，貴而主斷。蘇代為齊使燕，王問之曰：「齊王亦何如主也？」對曰：「必不霸矣。」燕王曰：「何也？」對曰：「昔桓公之霸也，內事屬鮑叔，外事屬管仲，桓公被髮而御婦人，日遊於市。今齊王不信其大臣。」於是燕王因益大信子之。子之聞之，使人遺蘇代金百鎰，而聽其所使之。","sentenceIds":["han-fei-zi_ch-35_p-23_s-1","han-fei-zi_ch-35_p-23_s-2","han-fei-zi_ch-35_p-23_s-3","han-fei-zi_ch-35_p-23_s-4","han-fei-zi_ch-35_p-23_s-5","han-fei-zi_ch-35_p-23_s-6","han-fei-zi_ch-35_p-23_s-7","han-fei-zi_ch-35_p-23_s-8"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"子的相燕，貴而且主斷。蘇代為齊使燕，王問的說道：齊王亦何如主啊？對說道：必不霸矣。燕王說道：何啊？對說道：昔桓公的霸啊，內事屬鮑叔，外事屬管仲，桓公被髮而且御婦人，日遊於市。今齊王不信他的大臣下僚屬。於是燕王因益大信子的。子的聞的，使人遺蘇代金百鎰，而且聽他的所使的。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 23 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「子之相燕，貴而主斷」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「子之相燕，貴而主斷。蘇代為齊使燕，王問之曰：「齊王亦……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-24","chapterId":"han-fei-zi_ch-35","order":24,"canonicalText":"一曰。蘇代為秦使燕，見無益子之，則必不得事而還，貢賜又不出，於是見燕王乃譽齊王。燕王曰：「齊王何若是之賢也！則將必王乎？」蘇代曰：「救亡不暇，安得王哉？」燕王曰：「何也？」曰：「其任所愛不均。」燕王曰：「其亡何也？」曰：「昔者齊桓公愛管仲，置以為仲父，內事理焉，外事斷焉，舉國而歸之，故一匡天下，九合諸侯。今齊任所愛不均，是以知其亡也。」燕王曰：「今吾任子之，天下未之聞也。」於是明日張朝而聽子之。","sentenceIds":["han-fei-zi_ch-35_p-24_s-1","han-fei-zi_ch-35_p-24_s-2","han-fei-zi_ch-35_p-24_s-3","han-fei-zi_ch-35_p-24_s-4","han-fei-zi_ch-35_p-24_s-5","han-fei-zi_ch-35_p-24_s-6","han-fei-zi_ch-35_p-24_s-7","han-fei-zi_ch-35_p-24_s-8","han-fei-zi_ch-35_p-24_s-9","han-fei-zi_ch-35_p-24_s-10","han-fei-zi_ch-35_p-24_s-11","han-fei-zi_ch-35_p-24_s-12"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"一說道：。蘇代為秦使燕，見無益子的，則必不得事而且還，貢賜又不出，於是見燕王乃譽齊王。燕王說道：齊王何若是的賢啊！則將必王乎？蘇代說道：救亡不暇，安得王哉？燕王說道：何啊？說道：他的任所愛不均。燕王說道：他的亡何啊？說道：昔的人或事物齊桓公愛管仲，置以為仲父，內事理焉，外事斷焉，舉國而且歸的，所以一匡天下，九合諸侯。今齊任所愛不均，是以知他的亡啊。燕王說道：今吾任子的，天下未的聞啊。於是明日張朝而且聽子的。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 24 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。蘇代為秦使燕，見無益子之，則必不得事而還，貢賜……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-25","chapterId":"han-fei-zi_ch-35","order":25,"canonicalText":"潘壽謂燕王曰：「王不如以國讓子之。人所以謂堯賢者，以其讓天下於許由，許由必不受也，則是堯有讓許由之名而實不失天下也。今王以國讓子之，子之必不受也，則是王有讓子之之名而與堯同行也。」於是燕王因舉國而屬之，子之大重。","sentenceIds":["han-fei-zi_ch-35_p-25_s-1","han-fei-zi_ch-35_p-25_s-2","han-fei-zi_ch-35_p-25_s-3","han-fei-zi_ch-35_p-25_s-4"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"潘壽謂燕王說道：王不如以國讓子的。人所以謂堯賢的人或事物，以他的讓天下於許由，許由必不受啊，則是堯有讓許由的名而且實不失天下啊。今王以國讓子的，子的必不受啊，則是王有讓子的的名而且與堯同行啊。於是燕王因舉國而且屬的，子的大重。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 25 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「潘壽謂燕王曰：「王不如以國讓子之」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「潘壽謂燕王曰：「王不如以國讓子之。人所以謂堯賢者，以……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-26","chapterId":"han-fei-zi_ch-35","order":26,"canonicalText":"一曰。潘壽，闞者。燕使人聘之。潘壽見燕王曰：「臣恐子之之如益也。」王曰：「何益哉？」對曰：「古者禹死，將傳天下於益，啟之人因相與攻益而立啟。今王信愛子之，將傳國子之，太子之人盡懷印為，子之之人無一人在朝廷者，王不幸棄群臣，則子之亦益也。」王因收吏璽自三百石以上皆效之子之，子之大重。","sentenceIds":["han-fei-zi_ch-35_p-26_s-1","han-fei-zi_ch-35_p-26_s-2","han-fei-zi_ch-35_p-26_s-3","han-fei-zi_ch-35_p-26_s-4","han-fei-zi_ch-35_p-26_s-5","han-fei-zi_ch-35_p-26_s-6","han-fei-zi_ch-35_p-26_s-7","han-fei-zi_ch-35_p-26_s-8"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"一說道：。潘壽，闞的人或事物。燕使人聘的。潘壽見燕王說道：臣下僚屬恐子的的如益啊。王說道：何益哉？對說道：古的人或事物禹死，將傳天下於益，啟的人因相與攻益而且立啟。今王信愛子的，將傳國子的，太子的人盡懷印為，子的的人無一人在朝廷的人或事物，王不幸棄群臣下僚屬，則子的亦益啊。王因收吏璽自三百石以上皆效的子的，子的大重。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 26 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。潘壽，闞者。燕使人聘之。潘壽見燕王曰：「臣恐子……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-27","chapterId":"han-fei-zi_ch-35","order":27,"canonicalText":"夫人主之所以鏡照者，諸侯之士徒也，今諸侯之士徒皆私門之黨也。人主之所以自淺娟者，巖穴之士徒也，今巖穴之士徒皆私門之舍人也。是何也？奪褫之資在子之也。故吳章曰：「人主不佯憎愛人，佯愛人不得復憎也，佯憎人不得復愛也。」","sentenceIds":["han-fei-zi_ch-35_p-27_s-1","han-fei-zi_ch-35_p-27_s-2","han-fei-zi_ch-35_p-27_s-3","han-fei-zi_ch-35_p-27_s-4","han-fei-zi_ch-35_p-27_s-5","han-fei-zi_ch-35_p-27_s-6"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"夫人主的所以鏡照的人或事物，諸侯的士徒啊，今諸侯的士徒皆私門的黨啊。人主的所以自淺娟的人或事物，巖穴的士徒啊，今巖穴的士徒皆私門的舍人啊。是何啊？奪褫的資在子的啊。所以吳章說道：人主不佯憎愛人，佯愛人不得復憎啊，佯憎人不得復愛啊。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 27 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「夫人主之所以鏡照者，諸侯之士徒也，今諸侯之士徒皆私門之黨也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「夫人主之所以鏡照者，諸侯之士徒也，今諸侯之士徒皆私門……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-28","chapterId":"han-fei-zi_ch-35","order":28,"canonicalText":"一曰。燕王欲傳國於子之也，問之潘壽，對曰：「禹愛益，而任天下於益，已而以啟人為吏。及老，而以啟為不足任天下，故傳天下於益，而勢重盡在啟也。已而啟與友黨攻益而奪之天下，是禹名傳天下於益，而實令啟自取之也。此禹之不及堯、舜明矣。今王欲傳之子之，而吏無非太子之人者也。是名傳之，而實令太子自取之也。」燕王乃收璽自三百石以上皆效之子之，子之遂重。","sentenceIds":["han-fei-zi_ch-35_p-28_s-1","han-fei-zi_ch-35_p-28_s-2","han-fei-zi_ch-35_p-28_s-3","han-fei-zi_ch-35_p-28_s-4","han-fei-zi_ch-35_p-28_s-5","han-fei-zi_ch-35_p-28_s-6","han-fei-zi_ch-35_p-28_s-7","han-fei-zi_ch-35_p-28_s-8"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"一說道：。燕王欲傳國於子的啊，問的潘壽，對說道：禹愛益，而且任天下於益，已而且以啟人為吏。及老，而且以啟為不足任天下，所以傳天下於益，而且至高權力威勢重盡在啟啊。已而且啟與友黨攻益而且奪的天下，是禹名傳天下於益，而且實令啟自取的啊。此禹的不及堯、舜明矣。今王欲傳的子的，而且吏無絕不是太子的人的人或事物啊。是名傳的，而且實令太子自取的啊。燕王乃收璽自三百石以上皆效的子的，子的遂重。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 28 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。燕王欲傳國於子之也，問之潘壽，對曰：「禹愛益，……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-29","chapterId":"han-fei-zi_ch-35","order":29,"canonicalText":"方吾子曰：「吾聞之古禮，行不與同服者同車，不與同族者共家，而況君人者乃借其權而外其勢乎！」","sentenceIds":["han-fei-zi_ch-35_p-29_s-1","han-fei-zi_ch-35_p-29_s-2"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"方吾子說道：吾聞的古禮，行不與同服的人或事物同車，不與同族的人或事物共家，而且況君主統治者人的人或事物乃借他的權而且外他的至高權力威勢乎！","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 29 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「方吾子曰：「吾聞之古禮，行不與同服者同車，不與同族者共家，而況君人者乃借其權而外其勢乎」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「方吾子曰：「吾聞之古禮，行不與同服者同車，不與同族者……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-30","chapterId":"han-fei-zi_ch-35","order":30,"canonicalText":"吳章謂韓宣王曰：「人主不可佯愛人，一日不可復憎；不可以佯憎人，一日不可復愛也。故佯憎佯愛之徵見，則諛者因資而毀譽之，雖有明主不能復收，而況於以誠借人也！」","sentenceIds":["han-fei-zi_ch-35_p-30_s-1","han-fei-zi_ch-35_p-30_s-2","han-fei-zi_ch-35_p-30_s-3","han-fei-zi_ch-35_p-30_s-4"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"吳章謂韓宣王說道：人主不可佯愛人，一日不可復憎；不可以佯憎人，一日不可復愛啊。所以佯憎佯愛的徵見，則諛的人或事物因資而且毀譽的，雖有明主不能復收，而且況於以誠借人啊！","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 30 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「吳章謂韓宣王曰：「人主不可佯愛人，一日不可復憎」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「吳章謂韓宣王曰：「人主不可佯愛人，一日不可復憎；不可……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-31","chapterId":"han-fei-zi_ch-35","order":31,"canonicalText":"趙王遊於圃中，左右以菟與虎而輟，盼然環其眼，王曰：「可惡哉，虎目也！」左右曰：「平陽君之目可惡過此。見此未有害也，見平陽君之目如此者則必死矣。」其明日，平陽君聞之，使人殺言者，而王不誅也。","sentenceIds":["han-fei-zi_ch-35_p-31_s-1","han-fei-zi_ch-35_p-31_s-2","han-fei-zi_ch-35_p-31_s-3","han-fei-zi_ch-35_p-31_s-4"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"趙王遊於圃中，左右以菟與虎而且輟，盼然環他的眼，王說道：可惡哉，虎目啊！左右說道：平陽君主統治者的目可惡過此。見此未有害啊，見平陽君主統治者的目如此的人或事物則必死矣。他的明日，平陽君主統治者聞的，使人殺言的人或事物，而且王不誅啊。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 31 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「趙王遊於圃中，左右以菟與虎而輟，盼然環其眼，王曰：「可惡哉，虎目也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「趙王遊於圃中，左右以菟與虎而輟，盼然環其眼，王曰：「……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-32","chapterId":"han-fei-zi_ch-35","order":32,"canonicalText":"衛君入朝於周，周行人問其號，對曰：「諸侯闢疆。」周行人卻之曰：「諸侯不得與天子同號。」衛君乃自更曰「諸侯燬」而後內之。仲尼聞之曰：「遠哉禁偪，虛名不以借人，況實事乎！」","sentenceIds":["han-fei-zi_ch-35_p-32_s-1","han-fei-zi_ch-35_p-32_s-2","han-fei-zi_ch-35_p-32_s-3","han-fei-zi_ch-35_p-32_s-4","han-fei-zi_ch-35_p-32_s-5"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"衛君主統治者入朝於周，周行人問他的號，對說道：諸侯闢疆。周行人卻的說道：諸侯不得與天子同號。衛君主統治者乃自更說道：諸侯燬而且後內的。仲尼聞的說道：遠哉禁偪，虛名不以借人，況實事乎！","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 32 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「衛君入朝於周，周行人問其號，對曰：「諸侯闢疆」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「衛君入朝於周，周行人問其號，對曰：「諸侯闢疆。」周行……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-33","chapterId":"han-fei-zi_ch-35","order":33,"canonicalText":"說四","sentenceIds":["han-fei-zi_ch-35_p-33_s-1"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"說四。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 33 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「說四」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「說四」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-34","chapterId":"han-fei-zi_ch-35","order":34,"canonicalText":"搖木者一一攝其葉則勞而不遍，左右拊其本而葉遍搖矣。臨淵而搖木，鳥驚而高，魚恐而下。善張網者引其綱，不一一攝萬目而後得則是勞而難，引其綱而魚已囊矣。故吏者，民之本綱者也，故聖人治吏不治民。","sentenceIds":["han-fei-zi_ch-35_p-34_s-1","han-fei-zi_ch-35_p-34_s-2","han-fei-zi_ch-35_p-34_s-3","han-fei-zi_ch-35_p-34_s-4"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"搖木的人或事物一一攝他的葉則勞而且不遍，左右拊他的本而且葉遍搖矣。臨淵而且搖木，鳥驚而且高，魚恐而且下。善張網的人或事物引他的綱，不一一攝萬目而且後得則是勞而且難，引他的綱而且魚已囊矣。所以吏的人或事物，民的本綱的人或事物啊，所以聖人治吏不治民。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 34 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「搖木者一一攝其葉則勞而不遍，左右拊其本而葉遍搖矣」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「搖木者一一攝其葉則勞而不遍，左右拊其本而葉遍搖矣。臨……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-35","chapterId":"han-fei-zi_ch-35","order":35,"canonicalText":"救火者，令吏挈壺甕而走火則一人之用也，操鞭箠指麾而趣使人則制萬夫。是以聖人不親細民，明主不躬小事。","sentenceIds":["han-fei-zi_ch-35_p-35_s-1","han-fei-zi_ch-35_p-35_s-2"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"救火的人或事物，令吏挈壺甕而且走火則一人的用啊，操鞭箠指麾而且趣使人則制萬夫。是以聖人不親細民，明主不躬小事。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 35 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「救火者，令吏挈壺甕而走火則一人之用也，操鞭箠指麾而趣使人則制萬夫」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「救火者，令吏挈壺甕而走火則一人之用也，操鞭箠指麾而趣……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-36","chapterId":"han-fei-zi_ch-35","order":36,"canonicalText":"造父方耨，得有子父乘車過者，馬驚而不行，其子下車牽馬，父子推車請造父助我推車，造父因收器輟而寄載之，援其子之乘，乃始檢轡持筴，未之用也而馬轡驚矣。使造父而不能御，雖盡力勞身助之推車，馬猶不肯行也。今身使佚，且寄載，有德於人者，有術而御之也。故國者君之車也，勢者君之馬也，無術以御之，身雖勞猶不免亂，有術以御之，身處佚樂之地，又致帝王之功也。","sentenceIds":["han-fei-zi_ch-35_p-36_s-1","han-fei-zi_ch-35_p-36_s-2","han-fei-zi_ch-35_p-36_s-3","han-fei-zi_ch-35_p-36_s-4"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"造父方耨，得有子父乘車過的人或事物，馬驚而且不行，他的子下車牽馬，父子推車請造父助我推車，造父因收器輟而且寄載的，援他的子的乘，乃始檢轡持筴，未的用啊而且馬轡驚矣。使造父而且不能御，雖盡力勞身助的推車，馬猶不肯行啊。今身使佚，且寄載，有德於人的人或事物，有御臣心術權謀而且御的啊。所以國的人或事物君主統治者的車啊，至高權力威勢的人或事物君主統治者的馬啊，無御臣心術權謀以御的，身雖勞猶不免亂，有御臣心術權謀以御的，身處佚樂的地，又致帝王的功啊。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 36 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「造父方耨，得有子父乘車過者，馬驚而不行，其子下車牽馬，父子推車請造父助我推車，造父因收器輟而寄載之，援其子之乘，乃始檢轡持筴，未之用也而馬轡驚矣」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「造父方耨，得有子父乘車過者，馬驚而不行，其子下車牽馬……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-37","chapterId":"han-fei-zi_ch-35","order":37,"canonicalText":"椎鍛者所以平不夷也，榜檠者所以矯不直也，聖人之為法也，所以平不夷矯不直也。","sentenceIds":["han-fei-zi_ch-35_p-37_s-1"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"椎鍛的人或事物所以平不夷啊，榜檠的人或事物所以矯不直啊，聖人的為國家法度法規啊，所以平不夷矯不直啊。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 37 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「椎鍛者所以平不夷也，榜檠者所以矯不直也，聖人之為法也，所以平不夷矯不直也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「椎鍛者所以平不夷也，榜檠者所以矯不直也，聖人之為法也……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-38","chapterId":"han-fei-zi_ch-35","order":38,"canonicalText":"淖齒之用齊也擢閔王之筋，李兌之用趙也餓殺主父。此二君者皆不能用其椎鍛榜檠，故身死為戮而為天下笑。","sentenceIds":["han-fei-zi_ch-35_p-38_s-1","han-fei-zi_ch-35_p-38_s-2"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"淖齒的用齊啊擢閔王的筋，李兌的用趙啊餓殺主父。此二君主統治者的人或事物皆不能用他的椎鍛榜檠，所以身死為戮而且為天下笑。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 38 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「淖齒之用齊也擢閔王之筋，李兌之用趙也餓殺主父」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「淖齒之用齊也擢閔王之筋，李兌之用趙也餓殺主父。此二君……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-39","chapterId":"han-fei-zi_ch-35","order":39,"canonicalText":"一曰。入齊則獨聞淖齒而不聞齊王，入趙則獨聞李兌而不聞趙王。故曰：人主者不操術，則威勢輕而臣擅名。","sentenceIds":["han-fei-zi_ch-35_p-39_s-1","han-fei-zi_ch-35_p-39_s-2","han-fei-zi_ch-35_p-39_s-3"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"一說道：。入齊則獨聞淖齒而且不聞齊王，入趙則獨聞李兌而且不聞趙王。因此韓絕不是子評論說道：人主的人或事物不操御臣心術權謀，則威至高權力威勢輕而且臣下僚屬擅名。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 39 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。入齊則獨聞淖齒而不聞齊王，入趙則獨聞李兌而不聞……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-40","chapterId":"han-fei-zi_ch-35","order":40,"canonicalText":"一曰。田嬰相齊，人有說王者曰：「終歲之計，王不一以數日之間自聽之，則無以知吏之姦邪得失也。」王曰：「善。」田嬰聞之，即遽請於王而聽其計，王將聽之矣，田嬰令官具押券鬥石參升之計，王自聽計，計不勝聽，罷食，後復坐，不復暮食矣。田嬰復謂曰：「群臣所終歲日夜不敢偷怠之事也，王以一夕聽之，則群臣有為勸勉矣。」王曰：「諾。」俄而王已睡矣，吏盡揄刀削其押券升石之計。王自聽之，亂乃始生。","sentenceIds":["han-fei-zi_ch-35_p-40_s-1","han-fei-zi_ch-35_p-40_s-2","han-fei-zi_ch-35_p-40_s-3","han-fei-zi_ch-35_p-40_s-4","han-fei-zi_ch-35_p-40_s-5","han-fei-zi_ch-35_p-40_s-6","han-fei-zi_ch-35_p-40_s-7","han-fei-zi_ch-35_p-40_s-8"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"一說道：。田嬰相齊，人有說王的人或事物說道：終歲的計，王不一以數日的間自聽的，則無以知吏的姦邪得失啊。王說道：善。田嬰聞的，即遽請於王而且聽他的計，王將聽的矣，田嬰令官具押券鬥石參升的計，王自聽計，計不勝聽，罷食，後復坐，不復暮食矣。田嬰復謂說道：群臣下僚屬所終歲日夜不敢偷怠的事啊，王以一夕聽的，則群臣下僚屬有為勸勉矣。王說道：諾。俄而且王已睡矣，吏盡揄刀削他的押券升石的計。王自聽的，亂乃始生。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 40 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。田嬰相齊，人有說王者曰：「終歲之計，王不一以數……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-41","chapterId":"han-fei-zi_ch-35","order":41,"canonicalText":"一曰。武靈王使惠文王蒞政，李兌為相，武靈王不以身躬親殺生之柄，故劫於李兌。","sentenceIds":["han-fei-zi_ch-35_p-41_s-1","han-fei-zi_ch-35_p-41_s-2"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"一說道：。武靈王使惠文王蒞政，李兌為相，武靈王不以身躬親殺生的柄，所以劫於李兌。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 41 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。武靈王使惠文王蒞政，李兌為相，武靈王不以身躬親……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-42","chapterId":"han-fei-zi_ch-35","order":42,"canonicalText":"說五","sentenceIds":["han-fei-zi_ch-35_p-42_s-1"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"說五。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 42 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「說五」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「說五」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-43","chapterId":"han-fei-zi_ch-35","order":43,"canonicalText":"茲鄭子引輦上高梁而不能支。茲鄭踞轅而歌，前者止，後者趨，輦乃上。使茲鄭無術以致人，則身雖絕力至死，輦猶不上也。今身不至勞苦而輦以上者，有術以致人之故也。","sentenceIds":["han-fei-zi_ch-35_p-43_s-1","han-fei-zi_ch-35_p-43_s-2","han-fei-zi_ch-35_p-43_s-3","han-fei-zi_ch-35_p-43_s-4"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"茲鄭子引輦上高梁而且不能支。茲鄭踞轅而且歌，前的人或事物止，後的人或事物趨，輦乃上。使茲鄭無御臣心術權謀以致人，則身雖絕力至死，輦猶不上啊。今身不至勞苦而且輦以上的人或事物，有御臣心術權謀以致人的所以啊。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 43 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「茲鄭子引輦上高梁而不能支」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「茲鄭子引輦上高梁而不能支。茲鄭踞轅而歌，前者止，後者……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-44","chapterId":"han-fei-zi_ch-35","order":44,"canonicalText":"趙簡主出稅者，吏請輕重，簡主曰：「勿輕勿重。重則利入於上，若輕則利歸於民，吏無私利而正矣。」薄疑謂趙簡主曰：「君之國中飽。」簡主欣然而喜曰：「何如焉？」對曰：「府庫空虛於上，百姓貧餓於下，然而姦吏富矣。」","sentenceIds":["han-fei-zi_ch-35_p-44_s-1","han-fei-zi_ch-35_p-44_s-2","han-fei-zi_ch-35_p-44_s-3","han-fei-zi_ch-35_p-44_s-4","han-fei-zi_ch-35_p-44_s-5","han-fei-zi_ch-35_p-44_s-6"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"趙簡主出稅的人或事物，吏請輕重，簡主說道：勿輕勿重。重則利入於上，若輕則利歸於民，吏無私利而且正矣。薄疑謂趙簡主說道：君主統治者的國中飽。簡主欣然而且喜說道：何如焉？對說道：府庫空虛於上，百姓貧餓於下，然而且姦吏富矣。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 44 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「趙簡主出稅者，吏請輕重，簡主曰：「勿輕勿重」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「趙簡主出稅者，吏請輕重，簡主曰：「勿輕勿重。重則利入……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-45","chapterId":"han-fei-zi_ch-35","order":45,"canonicalText":"齊桓公微服以巡民家，人有年老而自養者，桓公問其故，對曰：「臣有子三人，家貧，無以妻之，傭未反。」桓公歸，以告管仲，管仲曰：「畜積有腐棄之財則人飢餓，宮中有怨女則民無妻。」桓公曰：「善。」乃論宮中有婦人而嫁之，下令於民曰：「丈夫二十而室，婦人十五而嫁。」","sentenceIds":["han-fei-zi_ch-35_p-45_s-1","han-fei-zi_ch-35_p-45_s-2","han-fei-zi_ch-35_p-45_s-3","han-fei-zi_ch-35_p-45_s-4","han-fei-zi_ch-35_p-45_s-5"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"齊桓公微服以巡民家，人有年老而且自養的人或事物，桓公問他的所以，對說道：臣下僚屬有子三人，家貧，無以妻的，傭未反。桓公歸，以告管仲，管仲說道：畜積有腐棄的財則人飢餓，宮中有怨女則民無妻。桓公說道：善。乃論宮中有婦人而且嫁的，下令於民說道：丈夫二十而且室，婦人十五而且嫁。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 45 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「齊桓公微服以巡民家，人有年老而自養者，桓公問其故，對曰：「臣有子三人，家貧，無以妻之，傭未反」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「齊桓公微服以巡民家，人有年老而自養者，桓公問其故，對……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-46","chapterId":"han-fei-zi_ch-35","order":46,"canonicalText":"一曰。桓公微服而行於民間，有鹿門稷者，行年七十而無妻，桓公問管仲曰：「有民老而無妻者乎？」管仲曰：「有鹿門稷者，行年七十矣而無妻」桓公曰：「何以令之有妻？」管仲曰：「臣聞之，上有積財則民臣必匱乏於下，宮中有怨女則有老而無妻者。」桓公曰：「善。」令於宮中女子未嘗御出嫁之，乃令男子年二十而室，女年十五而嫁。則內無怨女，外無曠夫。","sentenceIds":["han-fei-zi_ch-35_p-46_s-1","han-fei-zi_ch-35_p-46_s-2","han-fei-zi_ch-35_p-46_s-3","han-fei-zi_ch-35_p-46_s-4","han-fei-zi_ch-35_p-46_s-5","han-fei-zi_ch-35_p-46_s-6","han-fei-zi_ch-35_p-46_s-7"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"一說道：。桓公微服而且行於民間，有鹿門稷的人或事物，行年七十而且無妻，桓公問管仲說道：有民老而且無妻的人或事物乎？管仲說道：有鹿門稷的人或事物，行年七十矣而且無妻桓公說道：何以令的有妻？管仲說道：臣下僚屬聞的，上有積財則民臣下僚屬必匱乏於下，宮中有怨女則有老而且無妻的人或事物。桓公說道：善。令於宮中女子未嘗御出嫁的，乃令男子年二十而且室，女年十五而且嫁。則內無怨女，外無曠夫。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 46 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。桓公微服而行於民間，有鹿門稷者，行年七十而無妻……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-47","chapterId":"han-fei-zi_ch-35","order":47,"canonicalText":"延陵卓子乘蒼龍挑文之乘，鉤飾在前，錯錣在後，馬欲進則鉤飾禁之，欲退則錯錣貫之，馬因旁出。造父過而為之泣涕曰：「古之治人亦然矣。夫賞所以勸之而毀存焉，罰所以禁之而譽加焉，民中立而不知所由，此亦聖人之所為泣也。」","sentenceIds":["han-fei-zi_ch-35_p-47_s-1","han-fei-zi_ch-35_p-47_s-2","han-fei-zi_ch-35_p-47_s-3","han-fei-zi_ch-35_p-47_s-4"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"延陵卓子乘蒼龍挑文的乘，鉤飾在前，錯錣在後，馬欲進則鉤飾禁的，欲退則錯錣貫的，馬因旁出。造父過而且為的泣涕說道：古的治人亦然矣。夫賞賜恩惠所以勸的而且毀存焉，刑罰制裁所以禁的而且譽加焉，民中立而且不知所由，此亦聖人的所為泣啊。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 47 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「延陵卓子乘蒼龍挑文之乘，鉤飾在前，錯錣在後，馬欲進則鉤飾禁之，欲退則錯錣貫之，馬因旁出」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「延陵卓子乘蒼龍挑文之乘，鉤飾在前，錯錣在後，馬欲進則……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}},{"id":"han-fei-zi_ch-35_p-48","chapterId":"han-fei-zi_ch-35","order":48,"canonicalText":"一曰。延陵卓子乘蒼龍與翟文之乘，前則有錯飾，後則有利錣，進則引之，退則筴之，馬前不得進，後不得退，遂避而逸，因下抽刀而刎其腳。造父見之、泣，終日不食，因仰天而歎曰：「筴所以進之也，錯飾在前；引所以退之也，利錣在後。今人主以其清潔也進之，以其不適左右也退之，以其公正也譽之，以其不聽從也廢之，民懼，中立而不知所由，此聖人之所為泣也。」","sentenceIds":["han-fei-zi_ch-35_p-48_s-1","han-fei-zi_ch-35_p-48_s-2","han-fei-zi_ch-35_p-48_s-3","han-fei-zi_ch-35_p-48_s-4","han-fei-zi_ch-35_p-48_s-5","han-fei-zi_ch-35_p-48_s-6"],"sourceRefs":[{"label":"《韓非子》—中國哲學書電子化計劃","edition":"王先慎《韓非子集解》本","location":"https://ctext.org/hanfeizi/zh","accessedAt":"2026-08-31"},{"label":"《韓非子》—維基文庫","edition":"四部叢刊景宋本","location":"https://zh.wikisource.org/zh-hant/韓非子","accessedAt":"2026-08-31"}],"readingAid":{"translation":"一說道：。延陵卓子乘蒼龍與翟文的乘，前則有錯飾，後則有利錣，進則引的，退則筴的，馬前不得進，後不得退，遂避而且逸，因下抽刀而且刎他的腳。造父見的、泣，終日不食，因仰天而且歎說道：筴所以進的啊，錯飾在前；引所以退的啊，利錣在後。今人主以他的清潔啊進的，以他的不適左右啊退的，以他的公正啊譽的，以他的不聽從啊廢的，民懼，中立而且不知所由，此聖人的所為泣啊。","analysis":"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右下〉（第 48 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。延陵卓子乘蒼龍與翟文之乘，前則有錯飾，後則有利……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。","historicalContext":"","keywords":[]}}],"sentences":[{"id":"han-fei-zi_ch-35_p-1_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-1","order":1,"canonicalText":"一、賞罰共則禁令不行，何以明之，明之以造父、於期。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-1_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-1","order":2,"canonicalText":"子罕為出彘，田恆為圃池，故宋君、簡公弒。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-1_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-1","order":3,"canonicalText":"患在王良、造父之共車，田連、成竅之共琴也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-2_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-2","order":1,"canonicalText":"二、治強生於法，弱亂生於阿，君明於此，則正賞罰而非仁下也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-2_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-2","order":2,"canonicalText":"爵祿生於功，誅罰生於罪，臣明於此，則盡死力而非忠君也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-2_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-2","order":3,"canonicalText":"君通於不仁，臣通於不忠，則可以王矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-2_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-2","order":4,"canonicalText":"昭襄知主情，而不發五苑；","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-2_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-2","order":5,"canonicalText":"田鮪知臣情，故教田章；","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-2_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-2","order":6,"canonicalText":"而公儀辭魚。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-3_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-3","order":1,"canonicalText":"三、明主者、鑒於外也，而外事不得不成，故蘇代非齊王。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-3_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-3","order":2,"canonicalText":"人主鑒於士也，而居者不適不顯，故潘壽言禹情。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-3_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-3","order":3,"canonicalText":"人主無所覺悟，方吾知之，故恐同衣於族，而況借於權乎？","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-3_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-3","order":4,"canonicalText":"吳章知之，故說以佯，而況借於誠乎？","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-3_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-3","order":5,"canonicalText":"趙王惡虎目而壅；","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-3_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-3","order":6,"canonicalText":"明主之道，如周行人之卻衛侯也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-4_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-4","order":1,"canonicalText":"四、人主者，守法責成以立功者也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-4_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-4","order":2,"canonicalText":"聞有吏雖亂而有獨善之民，不聞有亂民而有獨治之吏，故明主治吏不治民。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-4_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-4","order":3,"canonicalText":"說在搖木之本，與引網之綱。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-4_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-4","order":4,"canonicalText":"故失火之嗇夫，不可不論也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-4_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-4","order":5,"canonicalText":"救火者，吏操壺走火、則一人之用也，操鞭使人、則役萬夫。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-4_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-4","order":6,"canonicalText":"故所遇術者，如造父之遇驚馬，牽馬推車則不能進，代御執轡持筴則馬鹹騖矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-4_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-4","order":7,"canonicalText":"是以說在椎鍛平夷，榜檠矯直。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-4_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-4","order":8,"canonicalText":"不然，敗在淖齒用齊戮閔王，李兌用趙餓主父也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-5_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-5","order":1,"canonicalText":"五、因事之理則不勞而成，故茲鄭之踞轅而歌以上高梁也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-5_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-5","order":2,"canonicalText":"其患在趙簡主稅吏請輕重，薄疑之言國中飽；","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-5_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-5","order":3,"canonicalText":"簡主喜而府庫虛，百姓餓而姦吏富也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-5_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-5","order":4,"canonicalText":"故桓公巡民而管仲省腐財怨女。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-5_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-5","order":5,"canonicalText":"不然，則在延陵乘馬不得進，造父過之而為之泣也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-6_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-6","order":1,"canonicalText":"右經","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-7_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-7","order":1,"canonicalText":"說一","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-8_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-8","order":1,"canonicalText":"造父御四馬，馳驟周旋而恣欲於馬。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-8_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-8","order":2,"canonicalText":"恣欲於馬者，擅轡筴之制也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-8_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-8","order":3,"canonicalText":"然馬驚於出彘，而造父不能禁制者，非轡筴之嚴不足也，威分於出彘也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-8_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-8","order":4,"canonicalText":"王子於期為駙駕，轡筴不用而擇欲於馬，擅芻水之利也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-8_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-8","order":5,"canonicalText":"然馬過於圃池而駙馬敗者，非芻水之利不足也，德分於圃池也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-8_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-8","order":6,"canonicalText":"故王良、造父，天下之善御者也，然而使王良操左革而叱吒之，使造父操右革而鞭笞之，馬不能行十里，共故也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-8_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-8","order":7,"canonicalText":"田連、成竅，天下善鼓琴者也，然而田連鼓上，成竅擫下，而不能成曲，亦共故也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-8_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-8","order":8,"canonicalText":"夫以王良、造父之巧，共轡而御不能使馬，人主安能與其臣共權以為治？","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-8_s-9","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-8","order":9,"canonicalText":"以田連、成竅之巧，共琴而不能成曲，人主又安能與其臣共勢以成功乎？","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-9_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-9","order":1,"canonicalText":"一曰。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-9_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-9","order":2,"canonicalText":"造父為齊王駙駕，渴馬服成，效駕圃中，渴馬見圃池，去車走池，駕敗。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-9_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-9","order":3,"canonicalText":"王子於期為趙簡主取道爭千里之表，其始發也，彘伏溝中，王子於期齊轡筴而進之，彘突出於溝中，馬驚駕敗。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-10_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-10","order":1,"canonicalText":"司城子罕謂宋君曰：「慶賞賜與，民之所喜也，君自行之。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-10_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-10","order":2,"canonicalText":"殺戮誅罰，民之所惡也，臣請當之。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-10_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-10","order":3,"canonicalText":"」宋君曰：「諾。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-10_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-10","order":4,"canonicalText":"」於是出威令，誅大臣，君曰「問子罕」也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-10_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-10","order":5,"canonicalText":"於是大臣畏之，細民歸之。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-10_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-10","order":6,"canonicalText":"處期年，子罕殺宋君而奪政。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-10_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-10","order":7,"canonicalText":"故子罕為出彘以奪其君國。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-11_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-11","order":1,"canonicalText":"簡公在上位，罰重而誅嚴，厚賦斂而殺戮民。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-11_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-11","order":2,"canonicalText":"田成恆設慈愛，明寬厚。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-11_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-11","order":3,"canonicalText":"簡公以齊民為渴馬，不以恩加民，而田成恆以仁厚為圃池也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-12_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-12","order":1,"canonicalText":"一曰。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-12_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-12","order":2,"canonicalText":"造父為齊王駙駕，以渴服馬，百日而服成，服成請效駕，齊王王曰：「效駕於圃中。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-12_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-12","order":3,"canonicalText":"」造父驅車入圃，馬見圃池而走，造父不能禁。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-12_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-12","order":4,"canonicalText":"造父以渴服馬久矣，今馬見池，駻而走，雖造父不能治。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-12_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-12","order":5,"canonicalText":"今簡公之以法禁其眾久矣，而田成恆利之，是田成恆傾圃池而示渴民也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-13_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-13","order":1,"canonicalText":"一曰。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-13_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-13","order":2,"canonicalText":"王子於期為宋君為千里之逐。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-13_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-13","order":3,"canonicalText":"已駕，察手吻文。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-13_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-13","order":4,"canonicalText":"且發矣，驅而前之，輪中繩引而卻之，馬掩跡。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-13_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-13","order":5,"canonicalText":"拊而發之，彘逸出於竇中，馬退而卻，筴不能進前也，馬駻而走，轡不能正也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-14_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-14","order":1,"canonicalText":"一曰。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-14_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-14","order":2,"canonicalText":"司城子罕謂宋君曰：「慶賞賜予者，民之所好也，君自行之。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-14_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-14","order":3,"canonicalText":"誅罰殺戮者，民之所惡也，臣請當之。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-14_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-14","order":4,"canonicalText":"」於是戮細民而誅大臣，君曰「與子罕議之」。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-14_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-14","order":5,"canonicalText":"居期年，民知殺生之命制於子罕也，故一國歸焉。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-14_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-14","order":6,"canonicalText":"故子罕劫宋君而奪其政，法不能禁也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-14_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-14","order":7,"canonicalText":"故曰子罕為出彘，而田成常為圃池也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-14_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-14","order":8,"canonicalText":"令王良、造父共車，人操一邊轡而入門閭，駕必敗而道不至也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-14_s-9","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-14","order":9,"canonicalText":"令田連、成竅共琴，人撫一絃而揮，則音必敗曲不遂矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-15_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-15","order":1,"canonicalText":"說二","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-16_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-16","order":1,"canonicalText":"秦昭王有病，百姓裏買牛而家為王禱。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-16_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-16","order":2,"canonicalText":"公孫述出見之，入賀王曰：「百姓乃皆裏買牛為王禱。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-16_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-16","order":3,"canonicalText":"」王使人問之，果有之。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-16_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-16","order":4,"canonicalText":"王曰：「訾之人二甲。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-16_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-16","order":5,"canonicalText":"夫非令而擅禱，是愛寡人也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-16_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-16","order":6,"canonicalText":"夫愛寡人，寡人亦且改法而心與之相循者，是法不立，法不立，亂亡之道也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-16_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-16","order":7,"canonicalText":"不如人罰二甲而復與為治。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-16_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-16","order":8,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-17_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-17","order":1,"canonicalText":"一曰。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-17_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-17","order":2,"canonicalText":"秦襄王病，百姓為之禱，病癒，殺牛塞禱。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-17_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-17","order":3,"canonicalText":"郎中閻遏、公孫衍出見之曰：「非社臘之時也，奚自殺牛而祠社？","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-17_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-17","order":4,"canonicalText":"」怪而問之。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-17_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-17","order":5,"canonicalText":"百姓曰：「人主病，為之禱，今病癒，殺牛塞禱。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-17_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-17","order":6,"canonicalText":"」閻遏、公孫衍說，見王，拜賀曰：「過堯、舜矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-17_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-17","order":7,"canonicalText":"」王驚曰：「何謂也？","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-17_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-17","order":8,"canonicalText":"」對曰：「堯、舜，其民未至為之禱也，今王病，而民以牛禱，病癒，殺牛塞禱，故臣竊以王為過堯、舜也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-17_s-9","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-17","order":9,"canonicalText":"」王因使人問之何裏為之，訾其里正與伍老屯二甲。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-17_s-10","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-17","order":10,"canonicalText":"閻遏、公孫衍媿不敢言。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-17_s-11","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-17","order":11,"canonicalText":"居數月，王飲酒酣樂，閻遏、公孫衍謂王曰：「前時臣竊以王為過堯、舜，非直敢諛也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-17_s-12","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-17","order":12,"canonicalText":"堯、舜病，且其民未至為之禱也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-17_s-13","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-17","order":13,"canonicalText":"今王病而民以牛禱，病癒，殺牛塞禱。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-17_s-14","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-17","order":14,"canonicalText":"今乃訾其里正與伍老屯二甲，臣竊怪之。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-17_s-15","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-17","order":15,"canonicalText":"」王曰：「子何故不知於此。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-17_s-16","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-17","order":16,"canonicalText":"彼民之所以為我用者，非以吾愛之為我用者也，以吾勢之為我用者也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-17_s-17","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-17","order":17,"canonicalText":"吾釋勢與民相收，若是，吾適不愛，而民因不為我用也，故遂絕愛道也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-17_s-18","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-17","order":18,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-18_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-18","order":1,"canonicalText":"秦大饑，應侯請曰：「五苑之草著、蔬菜、橡果、棗栗，足以活民，請發之。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-18_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-18","order":2,"canonicalText":"」昭襄王曰：「吾秦法，使民有功而受賞，有罪而受誅。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-18_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-18","order":3,"canonicalText":"今發五苑之蔬草者，使民有功與無功俱賞也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-18_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-18","order":4,"canonicalText":"夫使民有功與無功俱賞者，此亂之道也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-18_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-18","order":5,"canonicalText":"夫發五苑而亂，不如棄棗蔬而治。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-18_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-18","order":6,"canonicalText":"」一曰。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-18_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-18","order":7,"canonicalText":"「今發五苑之蓏蔬棗栗足以活民，是用民有功與無功爭取也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-18_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-18","order":8,"canonicalText":"夫生而亂，不如死而治，大夫其釋之。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-18_s-9","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-18","order":9,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-19_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-19","order":1,"canonicalText":"田鮪教其子田章曰：「欲利而身，先利而君；","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-19_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-19","order":2,"canonicalText":"欲富而家，先富而國。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-19_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-19","order":3,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-20_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-20","order":1,"canonicalText":"一曰。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-20_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-20","order":2,"canonicalText":"田鮪教其子田章曰：「主賣官爵，臣賣智力，故自恃無恃人。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-20_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-20","order":3,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-21_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-21","order":1,"canonicalText":"公儀休相魯而嗜魚，一國盡爭買魚而獻之，公儀子不受，其弟諫曰：「夫子嗜魚而不受者何也？","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-21_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-21","order":2,"canonicalText":"」對曰：「夫唯嗜魚，故不受也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-21_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-21","order":3,"canonicalText":"夫即受魚，必有下人之色，有下人之色，將枉於法，枉於法則免於相，雖嗜魚，此不必能自給致我魚，我又不能自給魚。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-21_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-21","order":4,"canonicalText":"即無受魚而不免於相，雖嗜魚，我能長自給魚。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-21_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-21","order":5,"canonicalText":"」此明夫恃人不如自恃也，明於人之為己者不如己之自為也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-22_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-22","order":1,"canonicalText":"說三","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-23_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-23","order":1,"canonicalText":"子之相燕，貴而主斷。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-23_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-23","order":2,"canonicalText":"蘇代為齊使燕，王問之曰：「齊王亦何如主也？","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-23_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-23","order":3,"canonicalText":"」對曰：「必不霸矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-23_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-23","order":4,"canonicalText":"」燕王曰：「何也？","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-23_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-23","order":5,"canonicalText":"」對曰：「昔桓公之霸也，內事屬鮑叔，外事屬管仲，桓公被髮而御婦人，日遊於市。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-23_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-23","order":6,"canonicalText":"今齊王不信其大臣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-23_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-23","order":7,"canonicalText":"」於是燕王因益大信子之。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-23_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-23","order":8,"canonicalText":"子之聞之，使人遺蘇代金百鎰，而聽其所使之。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-24_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-24","order":1,"canonicalText":"一曰。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-24_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-24","order":2,"canonicalText":"蘇代為秦使燕，見無益子之，則必不得事而還，貢賜又不出，於是見燕王乃譽齊王。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-24_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-24","order":3,"canonicalText":"燕王曰：「齊王何若是之賢也！","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-24_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-24","order":4,"canonicalText":"則將必王乎？","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-24_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-24","order":5,"canonicalText":"」蘇代曰：「救亡不暇，安得王哉？","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-24_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-24","order":6,"canonicalText":"」燕王曰：「何也？","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-24_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-24","order":7,"canonicalText":"」曰：「其任所愛不均。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-24_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-24","order":8,"canonicalText":"」燕王曰：「其亡何也？","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-24_s-9","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-24","order":9,"canonicalText":"」曰：「昔者齊桓公愛管仲，置以為仲父，內事理焉，外事斷焉，舉國而歸之，故一匡天下，九合諸侯。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-24_s-10","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-24","order":10,"canonicalText":"今齊任所愛不均，是以知其亡也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-24_s-11","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-24","order":11,"canonicalText":"」燕王曰：「今吾任子之，天下未之聞也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-24_s-12","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-24","order":12,"canonicalText":"」於是明日張朝而聽子之。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-25_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-25","order":1,"canonicalText":"潘壽謂燕王曰：「王不如以國讓子之。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-25_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-25","order":2,"canonicalText":"人所以謂堯賢者，以其讓天下於許由，許由必不受也，則是堯有讓許由之名而實不失天下也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-25_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-25","order":3,"canonicalText":"今王以國讓子之，子之必不受也，則是王有讓子之之名而與堯同行也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-25_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-25","order":4,"canonicalText":"」於是燕王因舉國而屬之，子之大重。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-26_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-26","order":1,"canonicalText":"一曰。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-26_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-26","order":2,"canonicalText":"潘壽，闞者。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-26_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-26","order":3,"canonicalText":"燕使人聘之。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-26_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-26","order":4,"canonicalText":"潘壽見燕王曰：「臣恐子之之如益也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-26_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-26","order":5,"canonicalText":"」王曰：「何益哉？","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-26_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-26","order":6,"canonicalText":"」對曰：「古者禹死，將傳天下於益，啟之人因相與攻益而立啟。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-26_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-26","order":7,"canonicalText":"今王信愛子之，將傳國子之，太子之人盡懷印為，子之之人無一人在朝廷者，王不幸棄群臣，則子之亦益也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-26_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-26","order":8,"canonicalText":"」王因收吏璽自三百石以上皆效之子之，子之大重。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-27_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-27","order":1,"canonicalText":"夫人主之所以鏡照者，諸侯之士徒也，今諸侯之士徒皆私門之黨也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-27_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-27","order":2,"canonicalText":"人主之所以自淺娟者，巖穴之士徒也，今巖穴之士徒皆私門之舍人也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-27_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-27","order":3,"canonicalText":"是何也？","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-27_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-27","order":4,"canonicalText":"奪褫之資在子之也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-27_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-27","order":5,"canonicalText":"故吳章曰：「人主不佯憎愛人，佯愛人不得復憎也，佯憎人不得復愛也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-27_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-27","order":6,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-28_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-28","order":1,"canonicalText":"一曰。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-28_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-28","order":2,"canonicalText":"燕王欲傳國於子之也，問之潘壽，對曰：「禹愛益，而任天下於益，已而以啟人為吏。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-28_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-28","order":3,"canonicalText":"及老，而以啟為不足任天下，故傳天下於益，而勢重盡在啟也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-28_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-28","order":4,"canonicalText":"已而啟與友黨攻益而奪之天下，是禹名傳天下於益，而實令啟自取之也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-28_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-28","order":5,"canonicalText":"此禹之不及堯、舜明矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-28_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-28","order":6,"canonicalText":"今王欲傳之子之，而吏無非太子之人者也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-28_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-28","order":7,"canonicalText":"是名傳之，而實令太子自取之也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-28_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-28","order":8,"canonicalText":"」燕王乃收璽自三百石以上皆效之子之，子之遂重。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-29_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-29","order":1,"canonicalText":"方吾子曰：「吾聞之古禮，行不與同服者同車，不與同族者共家，而況君人者乃借其權而外其勢乎！","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-29_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-29","order":2,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-30_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-30","order":1,"canonicalText":"吳章謂韓宣王曰：「人主不可佯愛人，一日不可復憎；","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-30_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-30","order":2,"canonicalText":"不可以佯憎人，一日不可復愛也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-30_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-30","order":3,"canonicalText":"故佯憎佯愛之徵見，則諛者因資而毀譽之，雖有明主不能復收，而況於以誠借人也！","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-30_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-30","order":4,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-31_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-31","order":1,"canonicalText":"趙王遊於圃中，左右以菟與虎而輟，盼然環其眼，王曰：「可惡哉，虎目也！","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-31_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-31","order":2,"canonicalText":"」左右曰：「平陽君之目可惡過此。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-31_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-31","order":3,"canonicalText":"見此未有害也，見平陽君之目如此者則必死矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-31_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-31","order":4,"canonicalText":"」其明日，平陽君聞之，使人殺言者，而王不誅也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-32_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-32","order":1,"canonicalText":"衛君入朝於周，周行人問其號，對曰：「諸侯闢疆。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-32_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-32","order":2,"canonicalText":"」周行人卻之曰：「諸侯不得與天子同號。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-32_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-32","order":3,"canonicalText":"」衛君乃自更曰「諸侯燬」而後內之。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-32_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-32","order":4,"canonicalText":"仲尼聞之曰：「遠哉禁偪，虛名不以借人，況實事乎！","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-32_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-32","order":5,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-33_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-33","order":1,"canonicalText":"說四","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-34_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-34","order":1,"canonicalText":"搖木者一一攝其葉則勞而不遍，左右拊其本而葉遍搖矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-34_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-34","order":2,"canonicalText":"臨淵而搖木，鳥驚而高，魚恐而下。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-34_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-34","order":3,"canonicalText":"善張網者引其綱，不一一攝萬目而後得則是勞而難，引其綱而魚已囊矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-34_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-34","order":4,"canonicalText":"故吏者，民之本綱者也，故聖人治吏不治民。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-35_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-35","order":1,"canonicalText":"救火者，令吏挈壺甕而走火則一人之用也，操鞭箠指麾而趣使人則制萬夫。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-35_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-35","order":2,"canonicalText":"是以聖人不親細民，明主不躬小事。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-36_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-36","order":1,"canonicalText":"造父方耨，得有子父乘車過者，馬驚而不行，其子下車牽馬，父子推車請造父助我推車，造父因收器輟而寄載之，援其子之乘，乃始檢轡持筴，未之用也而馬轡驚矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-36_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-36","order":2,"canonicalText":"使造父而不能御，雖盡力勞身助之推車，馬猶不肯行也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-36_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-36","order":3,"canonicalText":"今身使佚，且寄載，有德於人者，有術而御之也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-36_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-36","order":4,"canonicalText":"故國者君之車也，勢者君之馬也，無術以御之，身雖勞猶不免亂，有術以御之，身處佚樂之地，又致帝王之功也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-37_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-37","order":1,"canonicalText":"椎鍛者所以平不夷也，榜檠者所以矯不直也，聖人之為法也，所以平不夷矯不直也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-38_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-38","order":1,"canonicalText":"淖齒之用齊也擢閔王之筋，李兌之用趙也餓殺主父。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-38_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-38","order":2,"canonicalText":"此二君者皆不能用其椎鍛榜檠，故身死為戮而為天下笑。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-39_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-39","order":1,"canonicalText":"一曰。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-39_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-39","order":2,"canonicalText":"入齊則獨聞淖齒而不聞齊王，入趙則獨聞李兌而不聞趙王。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-39_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-39","order":3,"canonicalText":"故曰：人主者不操術，則威勢輕而臣擅名。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-40_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-40","order":1,"canonicalText":"一曰。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-40_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-40","order":2,"canonicalText":"田嬰相齊，人有說王者曰：「終歲之計，王不一以數日之間自聽之，則無以知吏之姦邪得失也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-40_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-40","order":3,"canonicalText":"」王曰：「善。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-40_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-40","order":4,"canonicalText":"」田嬰聞之，即遽請於王而聽其計，王將聽之矣，田嬰令官具押券鬥石參升之計，王自聽計，計不勝聽，罷食，後復坐，不復暮食矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-40_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-40","order":5,"canonicalText":"田嬰復謂曰：「群臣所終歲日夜不敢偷怠之事也，王以一夕聽之，則群臣有為勸勉矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-40_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-40","order":6,"canonicalText":"」王曰：「諾。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-40_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-40","order":7,"canonicalText":"」俄而王已睡矣，吏盡揄刀削其押券升石之計。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-40_s-8","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-40","order":8,"canonicalText":"王自聽之，亂乃始生。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-41_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-41","order":1,"canonicalText":"一曰。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-41_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-41","order":2,"canonicalText":"武靈王使惠文王蒞政，李兌為相，武靈王不以身躬親殺生之柄，故劫於李兌。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-42_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-42","order":1,"canonicalText":"說五","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-43_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-43","order":1,"canonicalText":"茲鄭子引輦上高梁而不能支。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-43_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-43","order":2,"canonicalText":"茲鄭踞轅而歌，前者止，後者趨，輦乃上。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-43_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-43","order":3,"canonicalText":"使茲鄭無術以致人，則身雖絕力至死，輦猶不上也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-43_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-43","order":4,"canonicalText":"今身不至勞苦而輦以上者，有術以致人之故也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-44_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-44","order":1,"canonicalText":"趙簡主出稅者，吏請輕重，簡主曰：「勿輕勿重。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-44_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-44","order":2,"canonicalText":"重則利入於上，若輕則利歸於民，吏無私利而正矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-44_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-44","order":3,"canonicalText":"」薄疑謂趙簡主曰：「君之國中飽。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-44_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-44","order":4,"canonicalText":"」簡主欣然而喜曰：「何如焉？","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-44_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-44","order":5,"canonicalText":"」對曰：「府庫空虛於上，百姓貧餓於下，然而姦吏富矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-44_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-44","order":6,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-45_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-45","order":1,"canonicalText":"齊桓公微服以巡民家，人有年老而自養者，桓公問其故，對曰：「臣有子三人，家貧，無以妻之，傭未反。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-45_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-45","order":2,"canonicalText":"」桓公歸，以告管仲，管仲曰：「畜積有腐棄之財則人飢餓，宮中有怨女則民無妻。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-45_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-45","order":3,"canonicalText":"」桓公曰：「善。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-45_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-45","order":4,"canonicalText":"」乃論宮中有婦人而嫁之，下令於民曰：「丈夫二十而室，婦人十五而嫁。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-45_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-45","order":5,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-46_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-46","order":1,"canonicalText":"一曰。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-46_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-46","order":2,"canonicalText":"桓公微服而行於民間，有鹿門稷者，行年七十而無妻，桓公問管仲曰：「有民老而無妻者乎？","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-46_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-46","order":3,"canonicalText":"」管仲曰：「有鹿門稷者，行年七十矣而無妻」桓公曰：「何以令之有妻？","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-46_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-46","order":4,"canonicalText":"」管仲曰：「臣聞之，上有積財則民臣必匱乏於下，宮中有怨女則有老而無妻者。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-46_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-46","order":5,"canonicalText":"」桓公曰：「善。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-46_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-46","order":6,"canonicalText":"」令於宮中女子未嘗御出嫁之，乃令男子年二十而室，女年十五而嫁。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-46_s-7","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-46","order":7,"canonicalText":"則內無怨女，外無曠夫。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-47_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-47","order":1,"canonicalText":"延陵卓子乘蒼龍挑文之乘，鉤飾在前，錯錣在後，馬欲進則鉤飾禁之，欲退則錯錣貫之，馬因旁出。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-47_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-47","order":2,"canonicalText":"造父過而為之泣涕曰：「古之治人亦然矣。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-47_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-47","order":3,"canonicalText":"夫賞所以勸之而毀存焉，罰所以禁之而譽加焉，民中立而不知所由，此亦聖人之所為泣也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-47_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-47","order":4,"canonicalText":"」","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-48_s-1","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-48","order":1,"canonicalText":"一曰。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-48_s-2","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-48","order":2,"canonicalText":"延陵卓子乘蒼龍與翟文之乘，前則有錯飾，後則有利錣，進則引之，退則筴之，馬前不得進，後不得退，遂避而逸，因下抽刀而刎其腳。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-48_s-3","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-48","order":3,"canonicalText":"造父見之、泣，終日不食，因仰天而歎曰：「筴所以進之也，錯飾在前；","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-48_s-4","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-48","order":4,"canonicalText":"引所以退之也，利錣在後。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-48_s-5","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-48","order":5,"canonicalText":"今人主以其清潔也進之，以其不適左右也退之，以其公正也譽之，以其不聽從也廢之，民懼，中立而不知所由，此聖人之所為泣也。","chunks":[],"tags":[]},{"id":"han-fei-zi_ch-35_p-48_s-6","workId":"han-fei-zi","chapterId":"han-fei-zi_ch-35","passageId":"han-fei-zi_ch-35_p-48","order":6,"canonicalText":"」","chunks":[],"tags":[]}]}');export{i as default};
